export const waveModels: WaveModel[] = rows.map((row, index) => {
  const [slug, family, section, focus, title, titleEn, blurb, blurbEn, formula, symbols, explain, explainEn, knobs, mode, preset] = row;
  return {
    no: index + 1,
    slug,
    family,
    section,
    focus,
    title,
    titleEn,
    blurb,
    blurbEn,
    formula,
    symbols,
    explain,
    explainEn,
    knobs,
    mode: mode ?? "mech",
    preset: preset ?? {},
  };
});

export function modelBySlug(slug: string) {
  return waveModels.find((model) => model.slug === slug) ?? null;
}

export function paramsOf(model: WaveModel) {
  return { ...baseParams, ...model.preset };
}
